content:
:root {
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --primary: #3b82f6;
  --primary-hover: #2563eb;
  --primary-light: #eff6ff;
  --store-a: #3b82f6;
  --store-b: #10b981;
  --store-c: #f59e0b;
  --breakpoint-sm: 600px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --primary: #3b82f6;
    --primary-hover: #60a5fa;
    --primary-light: #1e3a8a;
  }
}

body {
  margin: 0;
  padding: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  -webkit-font-smoothing: antialiased;
}

.app-container {
  max-width: 900px;
  margin: 0 auto;
  padding: 24px 16px;
  box-sizing: border-box;
}

.header {
  margin-bottom: 24px;
  text-align: center;
}

.title {
  font-size: 24px;
  font-weight: 700;
  margin: 0 0 8px 0;
  color: var(--text-main);
}

.subtitle {
  font-size: 14px;
  color: var(--text-muted);
  margin: 0;
}

.chart-card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03);
  margin-bottom: 20px;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 20px;
  justify-content: center;
}

.btn {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 500;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn:hover {
  background-color: var(--bg-color);
  color: var(--text-main);
  border-color: var(--text-muted);
}

.btn:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.btn-active {
  background-color: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
}

.btn-active:hover {
  background-color: var(--primary-hover);
  border-color: var(--primary-hover);
  color: #ffffff;
}

.store-legend {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 16px;
  font-size: 14px;
  color: var(--text-muted);
}

@media (prefers-reduced-motion: reduce) {
  .btn,
  .btn:hover {
    transition: none;
  }
}

@media (max-width: 600px) {
  .app-container {
    padding: 12px 8px;
  }

  .title {
    font-size: 20px;
  }

  .chart-card {
    padding: 12px;
  }
}

/**
 * 店舗の識別子（'all' または各店舗のID）
 */
export type StoreId = 'all' | 'storeA' | 'storeB' | 'storeC' | string;

/**
 * 月別の各店舗の来客数データ
 */
export interface MonthlyData {
  /** 対象月（例: '1月'） */
  month: string;
  /** 店舗Aの来客数 */
  storeA: number;
  /** 店舗Bの来客数 */
  storeB: number;
  /** 店舗Cの来客数 */
  storeC: number;
  [key: string]: string | number;
}

import { useState } from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import { MONTHLY_DATA, STORES } from './constants';
import './index.css';

export default function App() {
  const [activeStore, setActiveStore] = useState<'all' | 'storeA' | 'storeB' | 'storeC'>('all');

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">店舗別月別来客数比較</h1>
        <p className="subtitle">3つの店舗（A店・B店・C店）の年間来客数トレンドをご確認いただけます。</p>
      </header>

      <div className="chart-card">
        <div className="controls">
          <button
            className={`btn ${activeStore === 'all' ? 'btn-active' : ''}`}
            onClick={() => setActiveStore('all')}
            aria-pressed={activeStore === 'all'}
          >
            すべての店舗
          </button>
          {STORES.map((store) => (
            <button
              key={store.id}
              className={`btn ${activeStore === store.id ? 'btn-active' : ''}`}
              onClick={() => setActiveStore(store.id)}
              aria-pressed={activeStore === store.id}
            >
              {store.name}
            </button>
          ))}
        </div>

        <div style={{ width: '100%', height: 380 }}>
          <ResponsiveContainer>
            <LineChart
              data={MONTHLY_DATA}
              margin={{ top: 20, right: 20, left: -10, bottom: 5 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="month" stroke="#64748b" fontSize={12} />
              <YAxis stroke="#64748b" fontSize={12} />
              <Tooltip
                contentStyle={{
                  backgroundColor: '#ffffff',
                  borderColor: '#e2e8f0',
                  borderRadius: '8px',
                  boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.05)',
                  fontSize: '13px',
                }}
              />
              {STORES.map((store) => {
                if (activeStore !== 'all' && activeStore !== store.id) return null;
                return (
                  <Line
                    key={store.id}
                    type="monotone"
                    dataKey={store.id}
                    name={store.name}
                    stroke={store.color}
                    strokeWidth={3}
                    activeDot={{ r: 7 }}
                  />
                );
              })}
            </LineChart>
          </ResponsiveContainer>
        </div>

        <div className="store-legend">
          {STORES.map((store) => {
            if (activeStore !== 'all' && activeStore !== store.id) return null;
            return (
              <span key={store.id} style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                <span style={{ width: 12, height: 12, backgroundColor: store.color, borderRadius: '50%', display: 'inline-block' }}></span>
                {store.name}
              </span>
            );
          })}
        </div>
      </div>
    </div>
  );
}

